  const exact = cats.find((c) => c.id === id);
  if (exact) return { cat: exact, exact: true };
  const other = cats.find((c) => c.id === 'other') || cats.find((c) => c.kind === 'flexible') || cats[0];
  return { cat: other, exact: false };
}

// ---- Money ----
