  try { const c = cfgOf(); const m = String(levelKey === 'voiceThinkingLevel' ? (c.voiceModel || c.model) : c.model || '').toLowerCase(); if (level === 'minimal' && m.includes('pro')) level = 'low'; } catch (e) { /* ignore */ }
